import { chromium } from "playwright";
import { pathToFileURL } from "node:url";
import path from "node:path";

const root = "/Users/sinchunyeung/.treehouse/simplification-of-trajectory-streams-bec452/3/simplification-of-trajectory-streams/web";
const usability = path.join(root, "usability");

const freezeSpinners = `
  const style = document.createElement("style");
  style.textContent = ".button-spinner, .params-spinner { animation: none !important; transform: rotate(40deg); }";
  document.head.appendChild(style);
`;

const loadingState = (mobile) => `
  ${freezeSpinners}
  const dropHint = document.getElementById("dropHint");
  const hud = document.getElementById("traceLoadingHud");
  const uploadStatus = document.getElementById("uploadStatus");
  const paramsBar = document.getElementById("paramsBar");
  const canvas = document.getElementById("canvas");
  if (dropHint) dropHint.style.display = "none";
  if (canvas) canvas.classList.remove("has-trace");
  document.body.classList.add("trace-loading");
  if (${mobile ? "true" : "false"}) document.body.classList.add("trace-loaded-mobile");
  if (hud) {
    hud.classList.add("visible");
    hud.setAttribute("aria-hidden", "false");
  }
  if (uploadStatus) {
    uploadStatus.className = "sub upload-status-loading";
    uploadStatus.innerHTML = '<span class="button-spinner" aria-hidden="true"></span><span>Computing trace…</span>';
  }
  if (paramsBar) {
    paramsBar.innerHTML = [
      '<span class="params-metric params-metric--blue params-metric--frechet"><span class="params-metric-body"><span class="params-metric-label">Computed Fréchet distance</span><span class="params-metric-value params-metric-value--loading"><span class="button-spinner params-spinner" aria-hidden="true"></span></span></span></span>',
      '<span class="params-metric params-metric--blue params-metric--time"><span class="params-metric-body"><span class="params-metric-label">Simplification time</span><span class="params-metric-value params-metric-value--loading"><span class="button-spinner params-spinner" aria-hidden="true"></span></span></span></span>'
    ].join("");
  }
`;

const browser = await chromium.launch();

async function shot(page, url, viewport, out, evaluate) {
  await page.setViewportSize(viewport);
  await page.goto(url, { waitUntil: "domcontentloaded" });
  if (evaluate) await page.evaluate(evaluate);
  await page.waitForTimeout(200);
  await page.screenshot({ path: out, fullPage: false });
}

const page = await browser.newPage();
await shot(
  page,
  pathToFileURL(path.join(usability, "canvas-loading-hud.html")).href,
  { width: 1280, height: 900 },
  path.join(usability, "canvas-loading-hud.png"),
  freezeSpinners
);

await shot(
  page,
  pathToFileURL(path.join(root, "index.html")).href,
  { width: 1280, height: 800 },
  path.join(usability, "desktop-canvas-loading-hud-live.png"),
  loadingState(false)
);

await shot(
  page,
  pathToFileURL(path.join(root, "index.html")).href,
  { width: 390, height: 844 },
  path.join(usability, "mobile-canvas-loading-hud-live.png"),
  loadingState(true)
);

await browser.close();
console.log("wrote screenshots");

import { chromium } from "playwright";
import { pathToFileURL } from "node:url";
import path from "node:path";

const root = "/Users/sinchunyeung/.treehouse/simplification-of-trajectory-streams-bec452/3/simplification-of-trajectory-streams/web";
const usability = path.join(root, "usability");

const freezeSpinners = `
  const style = document.createElement("style");
  style.textContent = ".button-spinner, .params-spinner { animation: none !important; transform: rotate(40deg); }";
  document.head.appendChild(style);
`;

function loadingState({ mobile, params }) {
  return `
    ${freezeSpinners}
    const dropHint = document.getElementById("dropHint");
    const hud = document.getElementById("traceLoadingHud");
    const uploadStatus = document.getElementById("uploadStatus");
    const paramsBar = document.getElementById("paramsBar");
    const canvas = document.getElementById("canvas");
    if (dropHint) dropHint.style.display = "none";
    if (canvas) canvas.classList.remove("has-trace");
    document.body.classList.add("trace-loading");
    if (${mobile ? "true" : "false"}) document.body.classList.add("trace-loaded-mobile");
    if (hud) {
      hud.classList.add("visible");
      hud.setAttribute("aria-hidden", "false");
    }
    if (uploadStatus) {
      uploadStatus.className = "sub upload-status-loading";
      uploadStatus.innerHTML = '<span class="button-spinner" aria-hidden="true"></span><span>Computing trace…</span>';
    }
    if (paramsBar && ${params ? "true" : "false"}) {
      paramsBar.innerHTML = [
        '<span class="params-metric params-metric--blue params-metric--frechet"><span class="params-metric-body"><span class="params-metric-label">Computed Fréchet distance</span><span class="params-metric-value params-metric-value--loading"><span class="button-spinner params-spinner" aria-hidden="true"></span></span></span></span>',
        '<span class="params-metric params-metric--blue params-metric--time"><span class="params-metric-body"><span class="params-metric-label">Simplification time</span><span class="params-metric-value params-metric-value--loading"><span class="button-spinner params-spinner" aria-hidden="true"></span></span></span></span>'
      ].join("");
    }
  `;
}

const browser = await chromium.launch();
const page = await browser.newPage();

async function shot(url, viewport, out, evaluate) {
  await page.setViewportSize(viewport);
  await page.goto(url, { waitUntil: "domcontentloaded" });
  if (evaluate) await page.evaluate(evaluate);
  await page.waitForTimeout(250);
  await page.screenshot({ path: out, fullPage: false });
}

await shot(
  pathToFileURL(path.join(usability, "canvas-loading-hud.html")).href,
  { width: 1280, height: 900 },
  path.join(usability, "canvas-loading-hud.png"),
  freezeSpinners
);

await shot(
  pathToFileURL(path.join(root, "index.html")).href,
  { width: 1280, height: 800 },
  path.join(usability, "desktop-canvas-loading-hud-live.png"),
  loadingState({ mobile: false, params: false })
);

await shot(
  pathToFileURL(path.join(root, "index.html")).href,
  { width: 390, height: 844 },
  path.join(usability, "mobile-canvas-loading-hud-live.png"),
  loadingState({ mobile: true, params: true })
);

const checks = await page.evaluate(() => {
  const hud = document.getElementById("traceLoadingHud");
  const shown = getComputedStyle(hud).display;
  hud.classList.remove("visible");
  const hidden = getComputedStyle(hud).display;
  hud.classList.add("visible");
  return {
    shown,
    hidden,
    text: document.getElementById("traceLoadingText")?.textContent,
    importantKill: [...document.styleSheets].some((sheet) => {
      try {
        return [...sheet.cssRules].some((rule) =>
          String(rule.selectorText || "").includes("traceLoadingHud") &&
          String(rule.cssText).includes("none !important")
        );
      } catch {
        return false;
      }
    }),
    startOverflow: document.documentElement.scrollWidth,
  };
});

await browser.close();
console.log(JSON.stringify(checks, null, 2));

